function Button({ children, variant = 'primary', className = '', ...props }: { children: ReactNode; variant?: 'primary'|'outline'|'ghost'|'gold'; className?: string; [key:string]: unknown }) {
  const styles = { primary: 'bg-primary text-primary-foreground hover:-translate-y-0.5 hover:shadow-md', outline: 'border border-border text-foreground hover:border-primary hover:bg-secondary', ghost: 'text-muted-foreground hover:text-foreground hover:bg-secondary', gold: 'bg-accent text-accent-foreground hover:-translate-y-0.5 hover:shadow-md' };
  return <button className={`inline-flex items-center justify-center gap-2 rounded-md px-4 py-2.5 text-sm font-semibold ${styles[variant]} ${className}`} {...props}>{children}</button>;
}
function Badge({ children, tone = 'default' }: {children: ReactNode; tone?: 'default'|'gold'|'green'|'red'}) {
  const c = { default: 'bg-secondary text-muted-foreground', gold: 'bg-accent/20 text-[#785f20]', green: 'bg-[#dbece2] text-[#236044]', red: 'bg-[#f4dfdb] text-[#8d3b30]' };
  return <span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${c[tone]}`}>{children}</span>;
}
