function HomeRedirect() {
  const { isLoaded, isSignedIn } = useAuth();
  const { user } = useUser();
  if (!isLoaded || !isSignedIn) return <Home/>;
  const role = user?.publicMetadata?.role === 'admin' ? 'admin' : 'investor';
  return <Redirect to={role === 'admin' ? '/admin' : '/app'} />;
}
function ProtectedWorkspace({ admin = false }: { admin?: boolean }) {
  const { isLoaded, isSignedIn } = useAuth();
  const { user } = useUser();
  if (!isLoaded) return <Loading label="Checking your secure session" />;
  if (!isSignedIn) return <Redirect to="/sign-in" />;
  const role = user?.publicMetadata?.role === 'admin' ? 'admin' : 'investor';
  if (admin && role !== 'admin') return <Redirect to="/app" />;
  return <WorkspaceRouter admin={admin}/>;
}

function Investments() { return <PublicPage kicker="Investment menu" title="Strategies with a job to do."><div className="mb-10 max-w-2xl text-muted-foreground"><p>Each plan has a defined role, a stated time horizon, and a transparent cost. Select a strategy to understand the details before you decide.</p></div><PlanGrid/><div className="mt-12 rounded-lg border border-accent/40 bg-accent/10 p-6 text-sm text-primary"><strong>Important:</strong> Target returns are estimates, not guarantees. Capital is at risk and liquidity depends on the plan selected.</div></PublicPage>; }
