function Auth({kind}:{kind:'login'|'signup'|'forgot'|'verify'|'onboarding'}) { const [submitted,setSubmitted]=useState(false); const copy:any={login:['Welcome back.','Sign in to your private account.','Sign in'],signup:['A clearer start.','Create your TradeVerge account in a few minutes.','Create account'],forgot:['Reset access.','We will send a secure link to your inbox.','Send reset link'],verify:['One careful step.','Enter the verification code sent to your email.','Verify code'],onboarding:['Let’s set your course.','A few details help us show the right information.','Continue']}; const c=copy[kind]; return <div className="grid min-h-dvh bg-background lg:grid-cols-2"><div className="hidden bg-primary p-10 lg:flex lg:flex-col lg:justify-between"><Logo light/><div><p className="eyebrow text-accent">TradeVerge.live</p><h1 className="serif mt-5 max-w-md text-6xl leading-none text-[#f4efdf]">Thoughtful investing starts with a <em className="text-accent">clear view.</em></h1></div><p className="text-sm text-[#a9bdb0]">Private wealth principles. Modern access.</p></div><div className="flex items-center justify-center p-6"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Logo/></div><p className="eyebrow text-primary">Secure access</p><h1 className="serif mt-3 text-5xl text-primary">{c[0]}</h1><p className="mt-3 text-sm text-muted-foreground">{c[1]}</p>{submitted?<div className="mt-10 rounded-lg border border-accent/50 bg-accent/10 p-6"><Check className="h-6 w-6 text-primary"/><p className="mt-3 font-semibold text-primary">Request received</p><p className="mt-1 text-sm text-muted-foreground">This is a pending step. We will not mark anything complete until it is confirmed.</p></div>:<form className="mt-9 grid gap-5" onSubmit={e=>{e.preventDefault();setSubmitted(true)}}>{kind==='verify'?<Field label="Verification code" name="code" placeholder="000 000"/>:kind==='onboarding'?<><Field label="Full name" name="name" placeholder="Your name"/><Field label="Investment experience" name="experience" placeholder="Select one"/></>:<><Field label="Email address" name="email" type="email" placeholder="name@example.com"/>{kind!=='forgot'&&<Field label="Password" name="password" type="password" placeholder="At least 10 characters"/>}</>}<Button type="submit" className="mt-2">{c[2]} <ArrowRight className="h-4 w-4"/></Button></form>}<div className="mt-7 flex flex-wrap gap-3 text-sm text-muted-foreground">{kind==='login'?<><span>New here?</span><Link href="/signup" className="font-semibold text-primary" data-testid="link-auth-signup">Create an account</Link><Link href="/forgot-password" className="ml-auto text-primary" data-testid="link-forgot-password">Forgot password?</Link></>:<Link href="/login" className="font-semibold text-primary" data-testid="link-auth-login">Back to sign in</Link>}</div></div></div></div>; }
function Field({label,name,placeholder,type='text'}:{label:string;name:string;placeholder:string;type?:string}) { return <label className="grid gap-2 text-sm font-semibold text-primary">{label}<input required name={name} type={type} placeholder={placeholder} className="rounded-md border border-input bg-card px-3.5 py-3 font-normal text-foreground placeholder:text-muted-foreground" data-testid={`input-${name}`}/></label>; }

